    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def kthSmallest(self, mat: List[List[int]], k: int) -> int:\n        def merge(f: List[int], g: List[int], k: int) -> List[int]:\n            if len(g) > len(f):\n                return merge(g, f, k)\n            \n            q = [(f[0] + g[i], 0, i) for i in range(len(g))]\n            heapq.heapify(q)\n\n            ans = list()\n            while k and q:\n                entry = heapq.heappop(q)\n                ans.append(entry[0])\n                if entry[1] + 1 < len(f):\n                    heapq.heappush(q, (f[entry[1] + 1] + g[entry[2]], entry[1] + 1, entry[2]))\n                k -= 1\n            \n            return ans\n        \n        prev = mat[0]\n        for i in range(1, len(mat)):\n            prev = merge(prev, mat[i], k)\n        return prev[k - 1]\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.kthSmallest(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
