PBH12 = mk(
    "BH12",
    "\u5305\u542b\u6bcf\u4e2a\u67e5\u8be2\u7684\u6700\u5c0f\u533a\u95f4",
    "LeetCode 1851",
    "hard",
    "\u4e8c\u5206\u67e5\u627e",
    "\u7ed9\u4f60\u4e00\u4e2a\u4e8c\u7ef4\u6574\u6570\u6570\u7ec4 intervals \uff0c\u5176\u4e2d intervals[i] = [lefti, righti] \u8868\u793a\u7b2c i \u4e2a\u533a\u95f4\u5f00\u59cb\u4e8e lefti \u3001\u7ed3\u675f\u4e8e righti\uff08\u5305\u542b\u4e24\u4fa7\u53d6\u503c\uff0c\u95ed\u533a\u95f4\uff09\u3002\u533a\u95f4\u7684 \u957f\u5ea6 \u5b9a\u4e49\u4e3a\u533a\u95f4\u4e2d\u5305\u542b\u7684\u6574\u6570\u6570\u76ee\uff0c\u66f4\u6b63\u5f0f\u5730\u8868\u8fbe\u662f righti - lefti + 1 \u3002\n\n\u518d\u7ed9\u4f60\u4e00\u4e2a\u6574\u6570\u6570\u7ec4 queries \u3002\u7b2c j \u4e2a\u67e5\u8be2\u7684\u7b54\u6848\u662f\u6ee1\u8db3\u00a0lefti <= queries[j] <= righti \u7684 \u957f\u5ea6\u6700\u5c0f\u533a\u95f4 i \u7684\u957f\u5ea6 \u3002\u5982\u679c\u4e0d\u5b58\u5728\u8fd9\u6837\u7684\u533a\u95f4\uff0c\u90a3\u4e48\u7b54\u6848\u662f -1 \u3002\n\n\u4ee5\u6570\u7ec4\u5f62\u5f0f\u8fd4\u56de\u5bf9\u5e94\u67e5\u8be2\u7684\u6240\u6709\u7b54\u6848\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1aintervals = [[1,4],[2,4],[3,6],[4,4]], queries = [2,3,4,5]\n\u8f93\u51fa\uff1a[3,3,1,4]\n\u89e3\u91ca\uff1a\u67e5\u8be2\u5904\u7406\u5982\u4e0b\uff1a\n- Query = 2 \uff1a\u533a\u95f4 [2,4] \u662f\u5305\u542b 2 \u7684\u6700\u5c0f\u533a\u95f4\uff0c\u7b54\u6848\u4e3a 4 - 2 + 1 = 3 \u3002\n- Query = 3 \uff1a\u533a\u95f4 [2,4] \u662f\u5305\u542b 3 \u7684\u6700\u5c0f\u533a\u95f4\uff0c\u7b54\u6848\u4e3a 4 - 2 + 1 = 3 \u3002\n- Query = 4 \uff1a\u533a\u95f4 [4,4] \u662f\u5305\u542b 4 \u7684\u6700\u5c0f\u533a\u95f4\uff0c\u7b54\u6848\u4e3a 4 - 4 + 1 = 1 \u3002\n- Query = 5 \uff1a\u533a\u95f4 [3,6] \u662f\u5305\u542b 5 \u7684\u6700\u5c0f\u533a\u95f4\uff0c\u7b54\u6848\u4e3a 6 - 3 + 1 = 4 \u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1aintervals = [[2,3],[2,5],[1,8],[20,25]], queries = [2,19,5,22]\n\u8f93\u51fa\uff1a[2,-1,4,6]\n\u89e3\u91ca\uff1a\u67e5\u8be2\u5904\u7406\u5982\u4e0b\uff1a\n- Query = 2 \uff1a\u533a\u95f4 [2,3] \u662f\u5305\u542b 2 \u7684\u6700\u5c0f\u533a\u95f4\uff0c\u7b54\u6848\u4e3a 3 - 2 + 1 = 2 \u3002\n- Query = 19\uff1a\u4e0d\u5b58\u5728\u5305\u542b 19 \u7684\u533a\u95f4\uff0c\u7b54\u6848\u4e3a -1 \u3002\n- Query = 5 \uff1a\u533a\u95f4 [2,5] \u662f\u5305\u542b 5 \u7684\u6700\u5c0f\u533a\u95f4\uff0c\u7b54\u6848\u4e3a 5 - 2 + 1 = 4 \u3002\n- Query = 22\uff1a\u533a\u95f4 [20,25] \u662f\u5305\u542b 22 \u7684\u6700\u5c0f\u533a\u95f4\uff0c\u7b54\u6848\u4e3a 25 - 20 + 1 = 6 \u3002\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= intervals.length <= 105\n\n\t1 <= queries.length <= 105\n\n\tintervals[i].length == 2\n\n\t1 <= lefti <= righti <= 107\n\n\t1 <= queries[j] <= 107",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1aintervals\u3001queries\u3002",
    "\u8f93\u51fa integer[] \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\r\n    def minInterval(self, intervals: List[List[int]], queries: List[int]) -> List[int]:\r\n        m = len(intervals)\r\n        intervals.sort(key=lambda x: x[0])  # \u5bf9\u533a\u95f4\u6839\u636e\u5de6\u8fb9\u754c\u505a\u5347\u5e8f\u6392\u5e8f\r\n        n = len(queries)\r\n        qs = []     # \u4e3a\u4e86\u5bf9\u67e5\u8be2\u503c\u8fdb\u884c\u5347\u5e8f\u6392\u5e8f\uff0c\u91cd\u6784\u67e5\u8be2\u6570\u7ec4\uff0c\u8bb0\u5f55\u6bcf\u4e2a\u67e5\u8be2\u503c\u539f\u6765\u7684\u7d22\u5f15\r\n        for i, query in enumerate(queries):\r\n            qs.append([query, i])\r\n        qs.sort(key=lambda x: x[0])         # \u5bf9\u91cd\u6784\u7684\u67e5\u8be2\u503c\u6570\u7ec4\u8fdb\u884c\u6392\u5e8f\r\n        ans = [-1, ] * n    # \u7ed3\u679c\u6570\u7ec4\uff0c\u521d\u59cb\u5316\u90fd\u4e3a-1\r\n        pq = []     # \u5bf9\u5907\u9009\u533a\u95f4\u6839\u636e\u533a\u95f4\u957f\u5ea6\u6784\u5efa\u5c0f\u9876\u5806\uff0c\u961f\u5217\u4e2d\u7684\u5143\u7d20\u662f\u4e00\u4e2a\u4e8c\u5143\u6570\u7ec4[\u533a\u95f4\u957f\u5ea6, \u533a\u95f4\u53f3\u8fb9\u754c]\r\n        i = 0   # \u641c\u7d22\u533a\u95f4\u7684\u6307\u9488\r\n        for (query, j) in qs:\r\n            # \u5c06\u6240\u6709\u5de6\u8fb9\u754c\u5c0f\u4e8e\u7b49\u4e8e\u5f53\u524d\u67e5\u8be2\u503c\u7684\u533a\u95f4\u52a0\u5165\u961f\u5217\uff0c\u76f8\u5f53\u4e8e\u6ee1\u8db3\u4e00\u534a\u7684\u6761\u4ef6\uff1alefti <= query\r\n            while i < m and query >= intervals[i][0]:\r\n                heapq.heappush(pq, [intervals[i][1] - intervals[i][0] + 1, intervals[i][1]])\r\n                i += 1\r\n            # \u5c06\u6240\u6709\u53f3\u8fb9\u754c\u5c0f\u4e8e\u5f53\u524d\u67e5\u8be2\u503c\u5f97\u533a\u95f4\u5f39\u51fa\u961f\u5217\uff0c\u76f8\u5f53\u4e8e\u4e0d\u6ee1\u8db3\u53e6\u4e00\u534a\u6761\u4ef6\uff1aquery <= righti\r\n            while pq and pq[0][1] < query:\r\n                heapq.heappop(pq)\r\n            # \u961f\u9996\u533a\u95f4\u5373\u4e3a\u6ee1\u8db3\u6761\u4ef6\u4e14\u957f\u5ea6\u6700\u5c0f\u7684\u533a\u95f4\uff1b\u5982\u679c\u961f\u5217\u4e3a\u7a7a\uff0c\u8bf4\u660e\u4e0d\u5b58\u5728\u6ee1\u8db3\u6761\u4ef6\u7684\u533a\u95f4\r\n            if pq:\r\n                ans[j] = pq[0][0]\r\n        return ans\r\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.minInterval(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
    "int_list",
    [["[[1,4],[2,4],[3,6],[4,4]]\n[2,3,4,5]", "[3,3,1,4]"], ["[[2,3],[2,5],[1,8],[20,25]]\n[2,19,5,22]", "[2,-1,4,6]"]],
    ["array", "binary-search", "sorting", "sweep-line", "heap-priority-queue", "\u4e8c\u5206\u67e5\u627e"],
    )
