    "hard",
    "\u4e8c\u5206\u67e5\u627e",
    "\u7ed9\u4f60\u4e00\u4e2a\u4e0b\u6807\u4ece 0\u00a0\u5f00\u59cb\u7684\u4e8c\u7ef4\u6574\u6570\u6570\u7ec4\u00a0flowers\u00a0\uff0c\u5176\u4e2d\u00a0flowers[i] = [starti, endi]\u00a0\u8868\u793a\u7b2c\u00a0i\u00a0\u6735\u82b1\u7684 \u82b1\u671f\u00a0\u4ece\u00a0starti\u00a0\u5230\u00a0endi\u00a0\uff08\u90fd \u5305\u542b\uff09\u3002\u540c\u65f6\u7ed9\u4f60\u4e00\u4e2a\u4e0b\u6807\u4ece 0\u00a0\u5f00\u59cb\u5927\u5c0f\u4e3a n\u00a0\u7684\u6574\u6570\u6570\u7ec4\u00a0people \uff0cpeople[i]\u00a0\u662f\u7b2c\u00a0i\u00a0\u4e2a\u4eba\u6765\u770b\u82b1\u7684\u65f6\u95f4\u3002\n\n\u8bf7\u4f60\u8fd4\u56de\u4e00\u4e2a\u5927\u5c0f\u4e3a n\u00a0\u7684\u6574\u6570\u6570\u7ec4\u00a0answer\u00a0\uff0c\u5176\u4e2d\u00a0answer[i]\u662f\u7b2c\u00a0i\u00a0\u4e2a\u4eba\u5230\u8fbe\u65f6\u5728\u82b1\u671f\u5185\u82b1\u7684\u00a0\u6570\u76ee\u00a0\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1aflowers = [[1,6],[3,7],[9,12],[4,13]], people = [2,3,7,11]\n\u8f93\u51fa\uff1a[1,2,2,2]\n\u89e3\u91ca\uff1a\u4e0a\u56fe\u5c55\u793a\u4e86\u6bcf\u6735\u82b1\u7684\u82b1\u671f\u65f6\u95f4\uff0c\u548c\u6bcf\u4e2a\u4eba\u7684\u5230\u8fbe\u65f6\u95f4\u3002\n\u5bf9\u6bcf\u4e2a\u4eba\uff0c\u6211\u4eec\u8fd4\u56de\u4ed6\u4eec\u5230\u8fbe\u65f6\u5728\u82b1\u671f\u5185\u82b1\u7684\u6570\u76ee\u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1aflowers = [[1,10],[3,3]], people = [3,3,2]\n\u8f93\u51fa\uff1a[2,2,1]\n\u89e3\u91ca\uff1a\u4e0a\u56fe\u5c55\u793a\u4e86\u6bcf\u6735\u82b1\u7684\u82b1\u671f\u65f6\u95f4\uff0c\u548c\u6bcf\u4e2a\u4eba\u7684\u5230\u8fbe\u65f6\u95f4\u3002\n\u5bf9\u6bcf\u4e2a\u4eba\uff0c\u6211\u4eec\u8fd4\u56de\u4ed6\u4eec\u5230\u8fbe\u65f6\u5728\u82b1\u671f\u5185\u82b1\u7684\u6570\u76ee\u3002\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= flowers.length <= 5 * 104\n\n\tflowers[i].length == 2\n\n\t1 <= starti <= endi <= 109\n\n\t1 <= people.length <= 5 * 104\n\n\t1 <= people[i] <= 109",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1aflowers\u3001people\u3002",
    "\u8f93\u51fa integer[] \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def fullBloomFlowers(self, flowers: List[List[int]], people: List[int]) -> List[int]:\n        cnt = collections.defaultdict(int)\n        for start, end in flowers:\n            cnt[start] += 1\n            cnt[end + 1] -= 1\n        arr = sorted(cnt.items())\n        m = len(people)\n        ans = [0] * m\n        j, curr = 0, 0\n        for p, i in sorted(zip(people, range(m))):\n            while j < len(arr) and arr[j][0] <= p:\n                curr += arr[j][1]\n                j += 1\n            ans[i] = curr\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.fullBloomFlowers(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
