PBH14 = mk(
    "BH14",
    "\u4f7f\u6570\u7ec4\u8fde\u7eed\u7684\u6700\u5c11\u64cd\u4f5c\u6570",
    "LeetCode 2009",
    "hard",
    "\u4e8c\u5206\u67e5\u627e",
    "\u7ed9\u4f60\u4e00\u4e2a\u6574\u6570\u6570\u7ec4\u00a0nums\u00a0\u3002\u6bcf\u4e00\u6b21\u64cd\u4f5c\u4e2d\uff0c\u4f60\u53ef\u4ee5\u5c06\u00a0nums\u00a0\u4e2d\u00a0\u4efb\u610f\u00a0\u4e00\u4e2a\u5143\u7d20\u66ff\u6362\u6210 \u4efb\u610f\u00a0\u6574\u6570\u3002\n\n\u5982\u679c\u00a0nums\u00a0\u6ee1\u8db3\u4ee5\u4e0b\u6761\u4ef6\uff0c\u90a3\u4e48\u5b83\u662f \u8fde\u7eed\u7684\u00a0\uff1a\n\n\tnums\u00a0\u4e2d\u6240\u6709\u5143\u7d20\u90fd\u662f \u4e92\u4e0d\u76f8\u540c\u00a0\u7684\u3002\n\n\tnums\u00a0\u4e2d \u6700\u5927\u00a0\u5143\u7d20\u4e0e\u00a0\u6700\u5c0f\u00a0\u5143\u7d20\u7684\u5dee\u7b49\u4e8e\u00a0nums.length - 1\u00a0\u3002\n\n\u6bd4\u65b9\u8bf4\uff0cnums = [4, 2, 5, 3]\u00a0\u662f \u8fde\u7eed\u7684\u00a0\uff0c\u4f46\u662f\u00a0nums = [1, 2, 3, 5, 6] \u4e0d\u662f\u8fde\u7eed\u7684\u00a0\u3002\n\n\u8bf7\u4f60\u8fd4\u56de\u4f7f nums\u00a0\u8fde\u7eed\u00a0\u7684 \u6700\u5c11\u00a0\u64cd\u4f5c\u6b21\u6570\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1anums = [4,2,5,3]\n\u8f93\u51fa\uff1a0\n\u89e3\u91ca\uff1anums \u5df2\u7ecf\u662f\u8fde\u7eed\u7684\u4e86\u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1anums = [1,2,3,5,6]\n\u8f93\u51fa\uff1a1\n\u89e3\u91ca\uff1a\u4e00\u4e2a\u53ef\u80fd\u7684\u89e3\u662f\u5c06\u6700\u540e\u4e00\u4e2a\u5143\u7d20\u53d8\u4e3a 4 \u3002\n\u7ed3\u679c\u6570\u7ec4\u4e3a [1,2,3,5,4] \uff0c\u662f\u8fde\u7eed\u6570\u7ec4\u3002\n```\n\n\u793a\u4f8b 3\uff1a\n\n```\n\u8f93\u5165\uff1anums = [1,10,100,1000]\n\u8f93\u51fa\uff1a3\n\u89e3\u91ca\uff1a\u4e00\u4e2a\u53ef\u80fd\u7684\u89e3\u662f\uff1a\n- \u5c06\u7b2c\u4e8c\u4e2a\u5143\u7d20\u53d8\u4e3a 2 \u3002\n- \u5c06\u7b2c\u4e09\u4e2a\u5143\u7d20\u53d8\u4e3a 3 \u3002\n- \u5c06\u7b2c\u56db\u4e2a\u5143\u7d20\u53d8\u4e3a 4 \u3002\n\u7ed3\u679c\u6570\u7ec4\u4e3a [1,2,3,4] \uff0c\u662f\u8fde\u7eed\u6570\u7ec4\u3002\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= nums.length <= 105\n\n\t1 <= nums[i] <= 109",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1anums\u3002",
    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def minOperations(self, nums: List[int]) -> int:\n        n = len(nums)\n        sortedUniqueNums = sorted((set(nums)))\n        res = n\n        j = 0\n        for i, left in enumerate(sortedUniqueNums):\n            right = left + n - 1\n            while j < len(sortedUniqueNums) and sortedUniqueNums[j] <= right:\n                res = min(res, n - (j - i + 1))\n                j += 1\n        return res\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.minOperations(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
    "int",
    [["[4,2,5,3]", "0"], ["[1,2,3,5,6]", "1"], ["[1,10,100,1000]", "3"]],
    ["array", "hash-table", "binary-search", "sliding-window", "\u4e8c\u5206\u67e5\u627e"],
    )
