    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def maxPower(self, stations: List[int], r: int, k: int) -> int:\n        n = len(stations)\n        cnt = [0] * (n + 1)\n\n        for i in range(n):\n            left = max(0, i - r)\n            right = min(n, i + r + 1)\n            cnt[left] += stations[i]\n            cnt[right] -= stations[i]\n\n        def check(val: int) -> bool:\n            diff = cnt.copy()\n            total = 0\n            remaining = k\n\n            for i in range(n):\n                total += diff[i]\n                if total < val:\n                    add = val - total\n                    if remaining < add:\n                        return False\n                    remaining -= add\n                    end = min(n, i + 2 * r + 1)\n                    diff[end] -= add\n                    total += add\n            return True\n\n        lo, hi = min(stations), sum(stations) + k\n        res = 0\n        while lo <= hi:\n            mid = (lo + hi) // 2\n            if check(mid):\n                res = mid\n                lo = mid + 1\n            else:\n                hi = mid - 1\n        return res\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.maxPower(_args[0], _args[1], _args[2])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
